const $=id=>document.getElementById(id),esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');let targetId='',workspace=null,objectUrl=null,previewFileId='',saveTimers=new Map();
const api=(path,opt={})=>window.EHSApi.request(path,opt);function statusText(s){return({submitted:'제출완료',evaluating:'채점중',completed:'평가완료',published:'결과공개'})[s]||s||'-'}function fmtBytes(n){n=Number(n||0);return n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}function kind(name){const e=String(name||'').split('.').pop().toLowerCase();if(['jpg','jpeg','png'].includes(e))return'image';if(e==='pdf')return'pdf';if(['xls','xlsx','ppt','pptx','doc','docx','hwp','hwpx'].includes(e))return e.startsWith('hwp')?'hwp':'office';return'other'}
function closePreview(){if(objectUrl){URL.revokeObjectURL(objectUrl);objectUrl=null}$('modal').classList.add('hidden');$('modalBody').innerHTML='';previewFileId=''}$('modalClose').onclick=closePreview;$('modal').onclick=e=>{if(e.target===$('modal'))closePreview()};$('modalDownload').onclick=()=>previewFileId&&window.EHSApi.download(`/api/partner/submission/files/${encodeURIComponent(previewFileId)}`,'증빙자료');
async function blob(id){return window.EHSApi.blob(`/api/partner/submission/files/${encodeURIComponent(id)}`)}
async function preview(id){const f=workspace.items.flatMap(i=>i.files||[]).find(x=>x.id===id);if(!f)return;if(window.AttachmentPreview){window.AttachmentPreview.init({getPreviewTicket:file=>api(`/api/partner/submission/files/${encodeURIComponent(file.id)}/preview-ticket`,{method:'POST',body:'{}'}),download:file=>window.EHSApi.download(`/api/partner/submission/files/${encodeURIComponent(file.id)}`,file.file_name),maxPreviewBytes:25*1024*1024,allowExternalViewers:false,onError:error=>console.error('scoring attachment preview failed',error)});return window.AttachmentPreview.open(f)}previewFileId=id;$('modalTitle').textContent=f.file_name;$('modalBody').innerHTML='<div class="modal-loading">파일을 불러오는 중...</div>';$('modal').classList.remove('hidden');try{const k=kind(f.file_name);if(k==='image'||k==='pdf'){const b=await blob(id);objectUrl=URL.createObjectURL(b);$('modalBody').innerHTML=k==='image'?`<div class="preview image"><img src="${objectUrl}" alt="${esc(f.file_name)}"></div>`:`<div class="preview"><iframe src="${objectUrl}" title="${esc(f.file_name)}"></iframe></div>`}else if(k==='office'||k==='hwp'){const t=await api(`/api/partner/submission/files/${encodeURIComponent(id)}/preview-ticket`,{method:'POST',body:'{}'});const note=k==='hwp'?'한글 파일은 Google 공식 지원 형식이 아니므로 문서에 따라 표시되지 않을 수 있습니다.':'Google 문서 뷰어로 표시하며 원본과 레이아웃이 일부 다를 수 있습니다.';$('modalBody').innerHTML=`<div class="preview-note">${note}</div><div class="preview"><iframe src="${esc(t.viewer_url)}" title="${esc(f.file_name)}" referrerpolicy="no-referrer"></iframe></div>`}else $('modalBody').innerHTML='<div class="modal-loading">이 형식은 다운로드하여 확인해 주세요.</div>'}catch(e){$('modalBody').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function filesHtml(files){return (files||[]).length?`<div class="files">${files.map(f=>`<div class="file"><span class="file-name">${esc(f.file_name)} · ${fmtBytes(f.file_size)}</span><span><button data-preview="${esc(f.id)}">미리보기</button><button data-download="${esc(f.id)}">다운로드</button></span></div>`).join('')}</div>`:'<div class="files"><div class="file"><span class="file-name">첨부된 증빙자료가 없습니다.</span></div></div>'}
function syncSummaryView(){const s=workspace?.summary;if(!s)return;const values=[Number(s.raw_score||0),Number(s.applicable_count||0),Number(s.unevaluated_count||0),Number(s.needs_rescore_count||0),Number(s.na_count||0),Number(s.undetermined_count||0)];document.querySelectorAll('.summary .metric b').forEach((el,index)=>{if(index<values.length)el.textContent=String(values[index])});const completeButton=document.getElementById('complete');if(completeButton)completeButton.disabled=!s.complete}
function scheduleSave(id){clearTimeout(saveTimers.get(id));const state=document.getElementById('state-'+id);if(state)state.textContent='변경됨';saveTimers.set(id,setTimeout(()=>{saveTimers.delete(id);save(id)},800))}
function heroActions(t,s){if(t.status==='published')return'<button class="btn" disabled>결과 공개완료</button>';if(t.status==='completed')return'<button class="btn primary" id="publish">결과 공개</button>';return`<button class="btn primary" id="complete" ${s.complete?'':'disabled'}>평가완료</button>`}
function render(){const t=workspace.target,s=workspace.summary;$('app').className='';$('app').innerHTML=`<section class="hero"><div><div class="eyebrow">${esc(t.cycle_name||'i-PaSS')} · ${statusText(t.status)}</div><h1>${esc(t.company_name)} 평가 채점</h1><div class="hero-meta">${esc(t.industry_name||'-')} · 제출일 ${esc(t.submitted_at?String(t.submitted_at).slice(0,10):'-')}</div></div><div class="hero-actions">${heroActions(t,s)}</div></section><div class="summary"><div class="metric"><span>현재 원점수</span><b>${Number(s.raw_score||0)}</b></div><div class="metric"><span>채점 대상</span><b>${s.applicable_count}</b></div><div class="metric attention"><span>미채점</span><b>${s.unevaluated_count}</b></div><div class="metric recheck"><span>재확인 필요</span><b>${s.needs_rescore_count||0}</b></div><div class="metric"><span>N/A</span><b>${s.na_count}</b></div><div class="metric attention"><span>판정 대기</span><b>${s.undetermined_count||0}</b></div></div>${workspace.items.map(i=>`<section class="item ${Number(i.needs_rescore)===1?'recheck':''}"><div class="item-head"><div><div class="item-title">${esc((i.item_code?i.item_code+' ':'')+i.item_name)}</div><div class="item-meta">${esc([i.parent_category_name,i.category_name].filter(Boolean).join(' · '))}</div></div><div class="item-badges">${Number(i.needs_rescore)===1?'<span class="recheck-badge">협력사 수정 · 재확인 필요</span>':''}<span class="chip">${i.item_type==='bonus'?'가점':'배점'} ${Number(i.max_score||0)}점</span></div></div><div class="item-body">${i.applicability_status==='undetermined'?`<div class="na">적용대상 판정 대기 · ${esc(i.applicability_reason||'업종·상시근로자 수 확인 필요')}</div>`:Number(i.applicable)===0?`<div class="na">N/A 항목${i.manual_na_reason?' · '+esc(i.manual_na_reason):''}</div>`:`<div><div class="submitted">${esc(i.description||'협력사 제출 설명이 없습니다.')}</div>${filesHtml(i.files)}</div><div><div class="score-grid"><div class="field"><label>점수</label><input type="number" min="0" max="${Number(i.max_score||0)}" step="0.1" data-score="${esc(i.id)}" value="${i.earned_score??''}"></div><div class="field"><label>평가 의견</label><textarea data-comment="${esc(i.id)}">${esc(i.evaluation_comment||'')}</textarea></div></div><div class="save-row"><span class="save-state" id="state-${esc(i.id)}"></span><button class="btn primary" data-save="${esc(i.id)}">${Number(i.needs_rescore)===1?'재확인 완료':'저장'}</button></div></div>`}</div></section>`).join('')}`;document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save(b.dataset.save));document.querySelectorAll('[data-score],[data-comment]').forEach(el=>el.oninput=()=>scheduleSave(el.dataset.score||el.dataset.comment));document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.preview));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>window.EHSApi.download(`/api/partner/submission/files/${encodeURIComponent(b.dataset.download)}`,'증빙자료'));if($('complete'))$('complete').onclick=complete;if($('publish'))$('publish').onclick=publish}
async function save(id){const button=document.querySelector(`[data-save="${CSS.escape(id)}"]`),state=$('state-'+id),item=workspace.items.find(row=>row.id===id);if(!button||!item)return;button.disabled=true;state.textContent='저장 중...';try{const score=document.querySelector(`[data-score="${CSS.escape(id)}"]`).value,comment=document.querySelector(`[data-comment="${CSS.escape(id)}"]`).value;if(score==='')throw new Error('점수를 입력하세요.');const result=await api(`/api/admin/evaluation-scoring/${encodeURIComponent(targetId)}/items/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({earned_score:score,evaluation_comment:comment,expected_updated_at:item.updated_at})});if(result.item)Object.assign(item,result.item);if(result.target)Object.assign(workspace.target,result.target);if(result.summary)workspace.summary=result.summary;const card=button.closest('.item');card?.classList.remove('recheck');card?.querySelector('.recheck-badge')?.remove();button.textContent='저장';state.textContent='저장됨';syncSummaryView()}catch(error){state.textContent=error.message;if(error.code==='SCORE_CONFLICT')setTimeout(load,300);else button.disabled=false}finally{if(button.isConnected)button.disabled=false}}
async function complete(){if(!confirm('모든 채점을 완료 처리할까요?'))return;try{const d=await api(`/api/admin/evaluation-scoring/${encodeURIComponent(targetId)}/complete`,{method:'POST',body:'{}'});workspace=d.workspace;render()}catch(e){alert(e.message)}}
async function publish(){if(!confirm('평가결과를 협력사에 공개할까요?'))return;try{const d=await api(`/api/admin/evaluation-scoring/${encodeURIComponent(targetId)}/publish`,{method:'POST',body:'{}'});workspace=d.workspace;render()}catch(e){alert(e.message)}}
async function load(){const d=await api(`/api/admin/evaluation-scoring/${encodeURIComponent(targetId)}`);workspace=d.workspace;render()}
$('back').onclick=()=>location.href='/ipass/evaluations';$('ipass').onclick=$('brand').onclick=()=>location.href='/ipass';$('home').onclick=()=>location.href='/home';$('logout').onclick=()=>window.EHSAuth.logout();(async()=>{try{targetId=new URLSearchParams(location.search).get('target')||'';if(!targetId)throw new Error('평가 대상 정보가 없습니다.');const u=await window.EHSAuth.requireUser({role:'admin'});$('user').textContent=[u.position,u.name].filter(Boolean).join(' ')||u.email;await load()}catch(e){if(e?.status===401)return;$('app').className='error';$('app').textContent=window.EHSApi.describe(e)}})();
